pub fn TRKPPCAccessSpecialReg<'a>(
    ctx: &'a Ctx,
    srcDestPtr: Addr<'a>,
    instructionData: Val<'a, u32>,
    read: i32,
) -> i32 {
    let __frame = ctx.stack_frame(0x10);
    let mut srcDestPtr = srcDestPtr;
    let mut instructionData = instructionData;
    let mut read = read;
    (Handle::add(instructionData, 4_i32)).set((0x4e800020_i32 as u32));
    fns::TRK_flush_cache(ctx, Handle::addr(instructionData), (20_i32 as u32));
    (Handle::cast::<FnPtr<'a>>(instructionData))
        .call::<_, ()>((srcDestPtr, fns::TRKvalue128_temp(ctx).at(0)));
    return (enums::kNoError as i32);
}

pub fn TRKTargetSetInputPendingPtr<'a>(ctx: &'a Ctx, ptr_: Addr<'a>) {
    let mut ptr_ = ptr_;
    fns::gTRKState(ctx).set_inputPendingPtr(Handle::cast::<Val<'a, u8>>(ptr_));
}

